#include <P1AM.h>

// Slot 1 = P1-08SIM inputs, slot 2 = P1-08TRS outputs
const int IN_SLOT = 1;
const int OUT_SLOT = 2;
bool pumpRun = false;

void setup() {
  while (!P1.init()) { ; }
}

void loop() {
  bool startPb = P1.readDiscrete(IN_SLOT, 1);   // NO start
  bool stopOk  = P1.readDiscrete(IN_SLOT, 2);   // NC stop: true = not pressed
  if (!stopOk) {
    pumpRun = false;
  } else if (startPb) {
    pumpRun = true;
  }
  P1.writeDiscrete(pumpRun, OUT_SLOT, 1);
}

#include <P1AM.h>
bool pumpRun = false;

void setup() {
  while (!P1.init()) {}
}

void loop() {
  bool startPb = P1.readDiscrete(1, 1);
  bool stopOk = P1.readDiscrete(1, 2);   // NC stop contact, healthy = true
  bool olOk = P1.readDiscrete(1, 3);     // NC overload contact
  pumpRun = (startPb || pumpRun) && stopOk && olOk;
  P1.writeDiscrete(pumpRun, 2, 1);
}

#include <P1AM.h>
bool pumpRun = false;
void setup() { while (!P1.init()) {} }
void loop() {
  if (!P1.readDiscrete(1, 2)) {          // NC stop opened
    pumpRun = false;
  } else if (P1.readDiscrete(1, 1)) {    // start
    pumpRun = true;
  }
  P1.writeDiscrete(pumpRun, 2, 1);
}

const int START1 = 2, STOP1 = 3, START2 = 4, STOP2 = 5;
const int M1 = 8, M10 = 9;
bool motor1 = false, motor10 = false;

void setup() {
  pinMode(START1, INPUT_PULLUP); pinMode(STOP1, INPUT_PULLUP);
  pinMode(START2, INPUT_PULLUP); pinMode(STOP2, INPUT_PULLUP);
  pinMode(M1, OUTPUT); pinMode(M10, OUTPUT);
}

void loop() {
  if (digitalRead(STOP1) == LOW) motor1 = false;
  else if (digitalRead(START1) == LOW) motor1 = true;

  if (digitalRead(STOP2) == LOW) motor10 = false;
  else if (digitalRead(START2) == LOW) motor10 = true;

  digitalWrite(M1, motor1);
  digitalWrite(M10, motor10);
}

const int START1 = 2, STOP1 = 3, START2 = 4, STOP2 = 5;
bool motor1 = false, motor2 = false;
void setup() {}
void loop() {
  bool s1 = digitalRead(START1) == LOW, p1 = digitalRead(STOP1) == LOW;
  bool s2 = digitalRead(START2) == LOW, p2 = digitalRead(STOP2) == LOW;
  // Motor 1
  if (s1) motor1 = true;
  if (p1) motor1 = false;
  // Motor 2
  if (s2) motor2 = true;
  if (p2) motor2 = false;
  digitalWrite(8, motor1);
  digitalWrite(9, motor2);
}

const int START_PIN = 2;
const int STOP_PIN = 3;
const int ESTOP_PIN = 4;
const int OL_PIN = 5;
const int GUARD_PIN = 6;
const int JOG_PIN = 7;
const int MOTOR_PIN = 8;
const int ALARM_PIN = 9;

bool motorRunning = false;
bool alarmOn = false;
unsigned long stopTimer = 0;
const unsigned long RUN_LIMIT_MS = 600000UL;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(ESTOP_PIN, INPUT_PULLUP);
  pinMode(OL_PIN, INPUT_PULLUP);
  pinMode(GUARD_PIN, INPUT_PULLUP);
  pinMode(JOG_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
  pinMode(ALARM_PIN, OUTPUT);
}

void loop() {
  bool startPressed = digitalRead(START_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;
  bool eStopPressed = digitalRead(ESTOP_PIN) == HIGH;   // NC e-stop opens when pressed
  bool overloadTripped = digitalRead(OL_PIN) == HIGH;
  bool guardClosed = digitalRead(GUARD_PIN) == LOW;
  bool jogPressed = digitalRead(JOG_PIN) == LOW;

  if (stopPressed) {
    motorRunning = false;
  } else if (startPressed) {
    motorRunning = true;
    stopTimer = millis();        // run-time limit starts now
  }
  if (motorRunning && millis() - stopTimer > RUN_LIMIT_MS) {
    motorRunning = false;
  }

  digitalWrite(MOTOR_PIN, motorRunning ? HIGH : LOW);
  digitalWrite(ALARM_PIN, alarmOn ? HIGH : LOW);
}

const int START_PIN = 2;
const int STOP_PIN = 3;
const int ESTOP_PIN = 4;
const int OL_PIN = 5;
const int GUARD_PIN = 6;
const int JOG_PIN = 7;
const int MOTOR_PIN = 8;
const int ALARM_PIN = 9;

bool motorRunning = false;
bool alarmOn = false;
bool stopRequested = false;
bool startRequested = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(ESTOP_PIN, INPUT_PULLUP);
  pinMode(OL_PIN, INPUT_PULLUP);
  pinMode(GUARD_PIN, INPUT_PULLUP);
  pinMode(JOG_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
  pinMode(ALARM_PIN, OUTPUT);
}

void loop() {
  bool startPressed = digitalRead(START_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;
  bool eStopPressed = digitalRead(ESTOP_PIN) == HIGH;   // NC e-stop opens when pressed
  bool overloadTripped = digitalRead(OL_PIN) == HIGH;
  bool guardClosed = digitalRead(GUARD_PIN) == LOW;
  bool jogPressed = digitalRead(JOG_PIN) == LOW;

  if (Serial.available()) {
    char c = Serial.read();
    if (c == 's') stopRequested = true;
    if (c == 'g') startRequested = true;
  }
  if (stopRequested || stopPressed || eStopPressed) {
    motorRunning = false;
    stopRequested = false;
    startRequested = false;
  } else if (startRequested || startPressed) {
    motorRunning = true;
    startRequested = false;
  }

  digitalWrite(MOTOR_PIN, motorRunning ? HIGH : LOW);
  digitalWrite(ALARM_PIN, alarmOn ? HIGH : LOW);
}

const int X_START = 2, X_STOP = 3, Y_OT_STOP = 4, Y_JOG = 5;
bool xRun = false, yEnable = true;
void setup() {}
void loop() {
  bool startPressed = digitalRead(X_START) == LOW;
  bool stopPressed = digitalRead(X_STOP) == LOW;
  bool yOvertravelStop = digitalRead(Y_OT_STOP) == LOW;
  if (yOvertravelStop) yEnable = false;
  if (startPressed) xRun = true;
  if (stopPressed) xRun = false;
  digitalWrite(8, xRun);
  digitalWrite(9, yEnable);
}

