  bool overloadTripped = digitalRead(OL_PIN) == HIGH;
  bool guardClosed = digitalRead(GUARD_PIN) == LOW;
  bool jogPressed = digitalRead(JOG_PIN) == LOW;

  switch (state) {
    case IDLE:
      motorRunning = false;
      if (startPressed && !stopPressed && !eStopPressed) state = RUNNING;
      break;
    case RUNNING:
      motorRunning = true;
      if (stopPressed || eStopPressed) state = IDLE;
      break;
  }

  digitalWrite(MOTOR_PIN, motorRunning ? HIGH : LOW);
  digitalWrite(ALARM_PIN, alarmOn ? HIGH : LOW);
}

const int START_PIN = 2;
const int STOP_PIN = 3;
const int MOTOR_PIN = 8;
const unsigned long DEBOUNCE_MS = 30;

bool motorRunning = false;
bool startStable = false, stopStable = false;
bool startLast = false, stopLast = false;
unsigned long startChanged = 0, stopChanged = 0;

bool debounce(bool raw, bool &last, bool &stable, unsigned long &changed) {
  if (raw != last) { last = raw; changed = millis(); }
  if (millis() - changed > DEBOUNCE_MS) stable = raw;
  return stable;
}

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
}

void loop() {
  bool startPressed = debounce(digitalRead(START_PIN) == LOW, startLast, startStable, startChanged);
  bool stopPressed  = debounce(digitalRead(STOP_PIN) == LOW, stopLast, stopStable, stopChanged);

  if (stopPressed) {
    motorRunning = false;
  } else if (startPressed) {
    motorRunning = true;
  }
  digitalWrite(MOTOR_PIN, motorRunning ? HIGH : LOW);
}

