// Fan controller
#define FAN_START 2
#define FAN_STOP  3
#define FAN_RELAY 8
bool fanOn = false;
unsigned long lastPrint = 0;

void setup() {
  Serial.begin(115200);
  pinMode(FAN_START, INPUT_PULLUP);
  pinMode(FAN_STOP, INPUT_PULLUP);
  pinMode(FAN_RELAY, OUTPUT);
}

void loop() {
  fanOn = (digitalRead(FAN_START) == LOW || fanOn) && digitalRead(FAN_STOP) == HIGH;
  digitalWrite(FAN_RELAY, fanOn);
  if (millis() - lastPrint > 1000) {
    lastPrint = millis();
    Serial.print("Fan: ");
    Serial.println(fanOn ? "ON" : "OFF");
  }
}

