  pinMode(STOP_PB, INPUT_PULLUP);
  pinMode(GUARD_SW, INPUT_PULLUP);
  pinMode(MOTOR, OUTPUT);
}
void loop() {
  const bool start = !digitalRead(START_PB);
  const bool stop = !digitalRead(STOP_PB);
  const bool guardOpen = digitalRead(GUARD_SW);
  if (stop || guardOpen) running = false;
  else if (start) running = true;
  digitalWrite(MOTOR, running);
}

