#include <P1AM.h>
// Three pumps. Slot 1: P1-08SIM (inputs), slot 2: P1-08TRS (outputs).
// Each stop is NC: input reads true while the stop is NOT pressed.
const int IN = 1, OUT = 2;
bool pumpRun[3] = { false, false, false };
const int startCh[3] = { 1, 3, 5 };
const int stopCh[3]  = { 2, 4, 6 };

void setup() {
  Serial.begin(115200);
  while (!P1.init()) { delay(10); }
}

void loop() {
  for (int i = 0; i < 3; i++) {
    bool startPb = P1.readDiscrete(IN, startCh[i]);
    bool stopOk  = P1.readDiscrete(IN, stopCh[i]);
    if (!stopOk) {
      pumpRun[i] = false;            // stop wins
    } else if (startPb) {
      pumpRun[i] = true;
    }
    P1.writeDiscrete(pumpRun[i], OUT, i + 1);
  }
}

FUNCTION_BLOCK FB_Motor
VAR_INPUT
  xStart : BOOL;
  xStop : BOOL;     (* NO stop: TRUE = pressed *)
  xOverload : BOOL;
END_VAR
VAR_OUTPUT
  xRun : BOOL;
END_VAR

IF xStop OR xOverload THEN
  xRun := FALSE;
ELSIF xStart THEN
  xRun := TRUE;
END_IF;

END_FUNCTION_BLOCK

class MotorCtl {
public:
  bool running = false;
  void update(bool start, bool stop) {
    if (stop) {
      running = false;
    } else if (start) {
      running = true;
    }
  }
};

MotorCtl motor;
void setup() { pinMode(2, INPUT_PULLUP); pinMode(3, INPUT_PULLUP); pinMode(8, OUTPUT); }
void loop() {
  motor.update(digitalRead(2) == LOW, digitalRead(3) == LOW);
  digitalWrite(8, motor.running);
}

