  if (stopPressed) { motorRunning = false; } else if (startPressed && !motorInhibit) { motorRunning = true; }
  if (eStopPressed) {
    motorInhibit = true;
    motorRunning = false;
  } else if (resetPressed) {
    motorInhibit = false;
  }

  digitalWrite(MOTOR_PIN, motorRunning ? HIGH : LOW);
  digitalWrite(ALARM_PIN, alarmOn ? HIGH : LOW);
}

PROGRAM Main
VAR
  Start AT %IX0.0 : BOOL;
  Stop AT %IX0.1 : BOOL;
  EStop AT %IX0.2 : BOOL;
  Overload AT %IX0.3 : BOOL;
  Guard AT %IX0.4 : BOOL;
  Jog AT %IX0.5 : BOOL;
  Motor AT %QX0.0 : BOOL;
  Alarm AT %QX0.1 : BOOL;
  EStopPressed, Reset, Interlock : BOOL;
END_VAR

IF EStopPressed THEN
  Interlock := TRUE;
END_IF;
IF Reset AND NOT EStopPressed THEN
  Interlock := FALSE;
END_IF;
Motor := (Start OR Motor) AND NOT Stop AND NOT Interlock;

END_PROGRAM

